def transform(grid):
    g=[r[:] for r in grid]
    R,C=len(g),len(g[0])
    centers=[]
    # Find solid 3x3 monochrome shapes.
    for r in range(R-2):
        for c in range(C-2):
            color=g[r][c]
            if color and all(g[i][j]==color for i in range(r,r+3) for j in range(c,c+3)):
                centers.append((color,r+1,c+1))
    # Each square extends a cross along its center row and column.
    lines=[]
    for color,r,c in centers:
        lines.append((color,[(r,j) for j in range(C) if not c-1<=j<=c+1]+[(i,c) for i in range(R) if not r-1<=i<=r+1]))
    claims={}
    for color,cells in lines:
        for p in cells: claims.setdefault(p,set()).add(color)
    for (r,c),colors in claims.items():
        if len(colors)==1: g[r][c]=next(iter(colors))
        else: g[r][c]=0
    return g
PY
